import { useMutation, useQueryClient } from "@tanstack/react-query";

export function useLike(postId: string) {
  const qc = useQueryClient();
  const key = ["post", postId];
  return useMutation({
    mutationFn: () => fetch(`/api/posts/${postId}/like`, { method: "POST" }),
    onMutate: async () => {
      await qc.cancelQueries({ queryKey: key });   // 防止旧请求覆盖乐观值
      const prev = qc.getQueryData<{ likes: number; liked: boolean }>(key);
      qc.setQueryData(key, (old: any) => ({ ...old, likes: old.likes + 1, liked: true }));
      return { prev };                              // 快照，用于回滚
    },
    onError: (_err, _vars, ctx) => {
      qc.setQueryData(key, ctx?.prev);              // 失败回滚
    },
    onSettled: () => qc.invalidateQueries({ queryKey: key }), // 以服务器为准
  });
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

function useTodos() {
  return useQuery({
    queryKey: ["todos"],
    queryFn: () => fetch("/api/todos").then(r => r.json()),
    staleTime: 30_000,   // 30 秒内视为新鲜，多组件共享不重复请求
  });
}

function useAddTodo() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (title: string) =>
      fetch("/api/todos", { method: "POST", body: JSON.stringify({ title }) }),
    // 写入成功后让列表失效，自动重新获取
    onSuccess: () => qc.invalidateQueries({ queryKey: ["todos"] }),
  });
}

